WITH exploded AS (SELECT id, host, level, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) x AS k, value) SELECT id, level, status_code, k, value, RANK() OVER (PARTITION BY k ORDER BY latency_ms DESC NULLS LAST) AS latency_ms_rank, PERCENT_RANK() OVER (PARTITION BY level ORDER BY latency_ms NULLS FIRST) AS latency_ms_percent_rank, AVG(status_code) OVER (PARTITION BY level ORDER BY status_code, id, k ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS status_code_avg_6_prior FROM exploded WHERE host = 'h1'
